insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"adjectives_basics_homework_q01_finish","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\adjectives_basics_homework.yaml","source_metadata":{}},{"key":"adjectives_basics_homework_q01_start","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\adjectives_basics_homework.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"adjectives_basics_homework_q01_finish","locale":"he","line_order":0,"content":"תראו. הציור יצא בדיוק כמו שתיארתם, ומחר הילדה מהפארק תקבל אותו במתנה.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_homework_q01_finish","locale":"he","line_order":1,"content":"זכרו: מילת התיאור באה לפני שם הדבר, a red apple = תפוח אדום. אחרי is או are היא באה בסוף, The apples are red = התפוחים אדומים.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_homework_q01_finish","locale":"he","line_order":2,"content":"כל הכבוד. עשיתם את שיעורי הבית לבד.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_homework_q01_start","locale":"he","line_order":0,"content":"שלום שוב. הילדה מהפארק עזרה לנו מאוד עם השלטים לתערוכה, ואני רוצה לצייר לה ציור במתנה.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_homework_q01_start","locale":"he","line_order":1,"content":"הפעם אצייר רק את מה שתתארו לי באנגלית. אם מילה אחת תהיה לא נכונה, גם הציור ייצא לא נכון.","line_format":"plain_text"},{"dialogue_key":"adjectives_basics_homework_q01_start","locale":"he","line_order":2,"content":"היום אין מילים חדשות. תראו לי לבד מה אתם כבר יודעים. האבן ליד העץ מחכה לכם.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
